import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { execFileSync, spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import test from 'node:test';

// Ordinary successful numeric source qualification only. Whole original modules
// execute directly, without registry loading, source rewriting or dep patches.
const ARCHIVE_SHA256 = 'ef24c4e1eabb9d694f9e311826264dd6111566dcdc74d62ad0d13cdd6cda47e1';
const DEFAULT_ARCHIVE = '/tmp/synapsis-workflow183-70ivyzc0/lobster-2026.9.16.tgz';
const DECIMAL_VECTORS = [
  [
    "1e400",
    "7ff0000000000000"
  ],
  [
    "-1e400",
    "fff0000000000000"
  ],
  [
    "1e-4000",
    "0000000000000000"
  ],
  [
    "-1e-4000",
    "8000000000000000"
  ],
  [
    "-0",
    "8000000000000000"
  ],
  [
    "-0.000e400",
    "8000000000000000"
  ],
  [
    "1.7976931348623157e308",
    "7fefffffffffffff"
  ],
  [
    "1.7976931348623158e308",
    "7fefffffffffffff"
  ],
  [
    "1.7976931348623159e308",
    "7ff0000000000000"
  ],
  [
    "-1.7976931348623158e308",
    "ffefffffffffffff"
  ],
  [
    "-1.7976931348623159e308",
    "fff0000000000000"
  ],
  [
    "",
    "7fefffffffffffff"
  ],
  [
    "",
    "7ff0000000000000"
  ],
  [
    "-",
    "fff0000000000000"
  ],
  [
    "2.2250738585072014e-308",
    "0010000000000000"
  ],
  [
    "2.225073858507201e-308",
    "000fffffffffffff"
  ],
  [
    "5e-324",
    "0000000000000001"
  ],
  [
    "2.4703282292062327e-324",
    "0000000000000000"
  ],
  [
    "2.4703282292062328e-324",
    "0000000000000001"
  ],
  [
    "0.",
    "0000000000000000"
  ],
  [
    "0.",
    "0000000000000001"
  ],
  [
    "-0.",
    "8000000000000000"
  ],
  [
    "-0.",
    "8000000000000001"
  ],
  [
    "9007199254740993",
    "4340000000000000"
  ],
  [
    "9007199254740995",
    "4340000000000002"
  ],
  [
    "-9007199254740993",
    "c340000000000000"
  ],
  [
    "1.00000000000000011102230246251565404236316680908203125",
    "3ff0000000000000"
  ],
  [
    "1.0000000000000001110223024625156540423631668090820312500000000000000001",
    "3ff0000000000001"
  ],
  [
    "-600",
    "3ff0000000000000"
  ],
  [
    "0.",
    "3ff0000000000000"
  ],
  [
    "1.",
    "3ff0000000000000"
  ],
  [
    "-291",
    "7ff0000000000000"
  ],
  [
    "-0.",
    "8000000000000000"
  ]
];

const bits = value => {
  const bytes = Buffer.alloc(8);
  bytes.writeDoubleBE(value);
  return bytes.toString('hex');
};
const fromBits = hex => Buffer.from(hex, 'hex').readDoubleBE();
const numericRoots = () => ['7ff0000000000000', 'fff0000000000000',
  '7ff8000000000000', '7ff8000000000042', '8000000000000000'].map(fromBits);
const collect = async iterable => {
  const output = [];
  for await (const item of iterable) output.push(item);
  return output;
};
const assertRoots = (actual, expected) => {
  assert.equal(actual.length, expected.length);
  actual.forEach((root, index) => assert.strictEqual(root, expected[index]));
};

async function runOracle() {
  const archive = process.env.SYNAPSIS_LOBSTER_NUMBER_ARCHIVE || DEFAULT_ARCHIVE;
  assert.equal(createHash('sha256').update(readFileSync(archive)).digest('hex'), ARCHIVE_SHA256);
  const directory = process.argv[process.argv.indexOf('--number-oracle-child') + 1];
  assert.ok(directory, 'owned extraction directory supplied by test parent');
  let commandCalls = 0;
  try {
    // Extract the entire pinned package unchanged into an owned directory.
    execFileSync('tar', ['-xzf', archive, '-C', directory], { timeout: 10_000, maxBuffer: 1024 * 1024 });
    const pkg = JSON.parse(readFileSync(join(directory, 'package/package.json'), 'utf8'));
    assert.equal(pkg.name, '@clawdbot/lobster');
    assert.equal(pkg.version, '2026.9.16');
    const commands = {};
    for (const [name, filename] of [['sort', 'sort'], ['where', 'where'], ['dedupe', 'dedupe'],
      ['groupBy', 'group_by'], ['map', 'map'], ['table', 'table'], ['template', 'template'], ['head', 'head']]) {
      const module = await import(pathToFileURL(join(directory, `package/dist/src/commands/stdlib/${filename}.js`)).href);
      commands[name] = module[`${name}Command`];
      assert.equal(commands[name].name, name);
    }
    async function run(name, input, args = {}, renderOutput = false) {
      let stdout = '';
      commandCalls += 1;
      const result = await commands[name].run({ input, args: { _: [], ...args },
        ctx: { renderOutput, stdout: { write: text => { stdout += text; return true; } } } });
      return { output: await collect(result.output), stdout, rendered: result.rendered === true };
    }

    // Native JSON/Buffer/String observations: these are not command executions.
    for (const [literal, expected] of DECIMAL_VECTORS) {
      assert.equal(bits(JSON.parse(literal)), expected, literal);
    }
    const ordered = JSON.parse('{"z":1e400,"2":-1e400,"\\ud800":-1e-4000,"z":1.7976931348623158e308}');
    assert.deepEqual(Object.keys(ordered), ['2', 'z', '\ud800']);
    assert.equal(bits(ordered.z), '7fefffffffffffff');
    assert.equal(bits(ordered['2']), 'fff0000000000000');
    assert.equal(bits(ordered['\ud800']), '8000000000000000');
    assert.equal(JSON.stringify(ordered), '{"2":null,"z":1.7976931348623157e+308,"\\ud800":0}');
    const roots = numericRoots();
    assert.deepEqual(roots.map(String), ['Infinity', '-Infinity', 'NaN', 'NaN', '0']);
    assert.equal(JSON.stringify(roots), '[null,null,null,null,0]');
    assert.equal(JSON.stringify(roots, null, 2), '[\n  null,\n  null,\n  null,\n  null,\n  0\n]');
    // Payload storage expectations in ExUnit apply to exact trusted tags. This
    // direct Buffer roundtrip observes the supplied quiet-NaN payload separately.
    assert.equal(bits(fromBits('7ff8000000000042')), '7ff8000000000042');
    assert.equal(JSON.stringify(Infinity), JSON.stringify(null));
    assert.equal(JSON.stringify(NaN), JSON.stringify(null));

    // Actual source command executions, with literal order/reference assertions.
    const numeric = ['7ff0000000000000', '4000000000000000', 'fff0000000000000',
      '8000000000000000', '0000000000000000', 'c014000000000000', '7ff0000000000000'].map(fromBits);
    for (const [args, indices] of [[{ key: 'n' }, [2, 5, 3, 4, 1, 0, 6]],
      [{ key: 'n', desc: true }, [0, 6, 1, 3, 4, 5, 2]]]) {
      const rows = numeric.map(n => ({ n }));
      assertRoots((await run('sort', rows, args)).output, indices.map(index => rows[index]));
    }
    // NaN comparator results become zero. The 3/NaN/1 case is deliberately
    // nontransitive; this literal is pinned to the actual Node source execution.
    for (const values of [[3, NaN, 1], [NaN, Infinity], [-Infinity, NaN]]) {
      const rows = values.map(n => ({ n }));
      assertRoots((await run('sort', rows, { key: 'n' })).output, rows);
    }

    // Parent executed the complete pinned source before product edits. This
    // nontransitive case exposes a real generic Enum.sort divergence.
    const nanOrderRows = [3, 1, 0, fromBits('7ff8000000000042'), 2].map(n => ({ n }));
    assertRoots((await run('sort', nanOrderRows, { key: 'n' })).output,
      [2, 1, 4, 0, 3].map(index => nanOrderRows[index]));

    const numericFields = [-Infinity, -2, -0, 0, 2, Infinity, fromBits('7ff8000000000042')];
    for (const [expression, indices] of [
      ['n=Infinity', [5]], ['n==1e400', [5]], ['n=-Infinity', [0]],
      ['n!=Infinity', [0, 1, 2, 3, 4, 6]], ['n<Infinity', [0, 1, 2, 3, 4]],
      ['n<=Infinity', [0, 1, 2, 3, 4, 5]], ['n>-Infinity', [1, 2, 3, 4, 5]],
      ['n>=-Infinity', [0, 1, 2, 3, 4, 5]], ['n=0', [2, 3]],
    ]) {
      const rows = numericFields.map(n => ({ n }));
      assertRoots((await run('where', rows, { _: [expression] })).output, indices.map(index => rows[index]));
    }
    for (const [expression, indices] of [
      ['n=Infinity', [0, 1, 5]], ['n=-Infinity', [2, 3]],
      ['n>0', [0, 1, 5]], ['n<=-1e400', [2, 3]],
    ]) {
      const rows = ['Infinity', '1e400', '-Infinity', '-1e400', '0', '  Infinity  '].map(n => ({ n }));
      assertRoots((await run('where', rows, { _: [expression] })).output, indices.map(index => rows[index]));
    }

    const rows = roots.slice(0, 4).map(n => ({ n }));
    assertRoots((await run('dedupe', rows, { key: 'n' })).output, [rows[0]]);
    const groups = (await run('groupBy', rows, { key: 'n' })).output;
    assert.equal(groups.length, 1);
    assert.deepEqual(Object.keys(groups[0]), ['key', 'items', 'count']);
    assert.equal(bits(groups[0].key), '7ff0000000000000');
    assertRoots(groups[0].items, rows);
    assert.equal(groups[0].count, 4);
    const unique = (await run('dedupe', roots.slice(0, 4))).output;
    assert.equal(unique.length, 1);
    assert.equal(bits(unique[0]), '7ff0000000000000');
    assert.deepEqual((await run('dedupe', [null, null])).output, [null]);

    const scalarTable = await run('table', roots, {}, true);
    assert.equal(scalarTable.stdout, 'Infinity\n-Infinity\nNaN\nNaN\n0\n');
    assert.equal(scalarTable.rendered, true);
    assert.deepEqual(scalarTable.output, []);
    const objectTable = await run('table', roots.slice(0, 3).map(n => ({ n })), {}, true);
    assert.equal(objectTable.stdout, 'n        \n---------\nInfinity \n-Infinity\nNaN      \n');
    const mapRows = roots.map(n => ({ n }));
    assertRoots((await run('map', mapRows, { _: ['shown={{n}}'] })).output, mapRows);
    assert.deepEqual(mapRows.map(row => row.shown), ['null', 'null', 'null', 'null', '0']);
    assert.deepEqual(mapRows.map(row => bits(row.n)), ['7ff0000000000000', 'fff0000000000000',
      '7ff8000000000000', '7ff8000000000042', '8000000000000000']);
    assert.deepEqual((await run('template', roots, { text: '{{.}}' })).output,
      ['Infinity', '-Infinity', 'NaN', 'NaN', '0']);
    assert.deepEqual((await run('template', roots, { text: '{{. | json}}' })).output,
      ['null', 'null', 'null', 'null', '0']);

    for (const [args, count] of [[{ n: 2.1 }, 3], [{ n: true }, 1], [{ n: false }, 0],
      [{ n: '0x2' }, 2], [{ n: ' 2e0 ' }, 2], [{ n: '' }, 0], [{ n: 0 }, 0],
      [{ n: null }, 0], [{ n: [] }, 0], [{ n: [2] }, 2], [{ n: [[2]] }, 2], [{}, 5]]) {
      const output = (await run('head', roots, args)).output;
      assert.deepEqual(output.map(bits), roots.slice(0, count).map(bits));
    }
    console.log(JSON.stringify({ archiveSha256: ARCHIVE_SHA256, sourcePackage: pkg.version,
      nativeObservations: ['JSON.parse', 'JSON.stringify', 'Buffer binary64', 'String'],
      wholeOriginalCommands: Object.keys(commands), commandCalls,
      runtime: { node: process.versions.node, v8: process.versions.v8 },
      nativeToolExecution: false, machineExecution: false, durableStorageExecution: false,
      dependencyPatches: false, sourceTransformed: false }));
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
}

if (process.argv.includes('--number-oracle-child')) {
  await runOracle();
} else {
  test('pinned whole Lobster ordinary numeric commands and separately labelled native binary64 observations',
    { timeout: 40_000 }, () => {
      // Parent owns extraction so even child timeout leaves a cleanup owner.
      const directory = mkdtempSync(join(tmpdir(), 'synapsis-number-source-'));
      try {
        const child = spawnSync(process.execPath,
          [fileURLToPath(import.meta.url), '--number-oracle-child', directory],
          { timeout: 30_000, encoding: 'utf8', maxBuffer: 1024 * 1024, env: process.env });
        assert.ifError(child.error);
        assert.equal(child.status, 0, child.stderr);
        const report = JSON.parse(child.stdout.trim());
        assert.equal(report.archiveSha256, ARCHIVE_SHA256);
        assert.deepEqual(report.wholeOriginalCommands,
          ['sort', 'where', 'dedupe', 'groupBy', 'map', 'table', 'template', 'head']);
        assert.equal(report.sourceTransformed, false);
        assert.equal(report.commandCalls, 40);
      } finally {
        rmSync(directory, { recursive: true, force: true });
      }
    });
}
